<template>
  <td>{{ $t('task_and_notification_cache') }}</td>
  <td>
    <f-toggle size="xs"
      :model-value="
        cache_data[get_task_and_notification_cache]?.enabled || false
      "
      @update:model-value="updateEnable($event)"
    />
  </td>
  <td>
    <div style="width: 300px">
      <q-input
        outlined
        dense
        tabindex="0"
        debounce="500"
        type="number"
        :class="'full-width'"
        :model-value="cache_data[get_task_and_notification_cache]?.ttl || 0"
        @update:model-value="updateTtl(Number($event))"
        hide-bottom-space
        :bottom-slots="false"
        style="padding: 5px 0px"
      >
        <q-tooltip>
          {{ $t('ttl_tooltip') }}
        </q-tooltip>
      </q-input>
    </div>
  </td>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import { storeToRefs } from 'pinia';
import { useSettingStore } from 'src/store/main';
import { DeliveryCache } from 'src/constants';
import helperMixin from 'src/mixins/helperMixin';
import { userApiService } from 'src/services';
export default defineComponent({
  components: {},
  el: '#app',
  mixins: [helperMixin],
  watch: {},
  data() {
    return {
      get_task_and_notification_cache:
        DeliveryCache.get_task_and_notification_cache,
    };
  },
  setup() {
    const settings_store = useSettingStore();
    const { loading_settings, cache_data } = storeToRefs(settings_store);
    const { getCachePreferences } = settings_store;

    return {
      cache_data,
      loading_settings,
      getCachePreferences,
    };
  },
  methods: {
    async updateEnable(value: boolean) {
      this.cache_data[this.get_task_and_notification_cache].enabled = value;
      await this.updateCache();
    },
    async updateTtl(value: number) {
      this.cache_data[this.get_task_and_notification_cache].ttl = value;
      await this.updateCache();
    },
    async updateCache() {
      const enabled =
        this.cache_data[this.get_task_and_notification_cache].enabled;
      const ttl = this.cache_data[this.get_task_and_notification_cache].ttl;
      try {
        const data = {
          key: this.get_task_and_notification_cache,
          cache_name: 'TN',
          enable: enabled,
          ttl: ttl || 0,
        };
        const response = await userApiService.setCachePreference(data);
        if (response.success === false) {
          throw response;
        }
        await this.getCachePreferences(this.get_task_and_notification_cache);
        notify.success(this.$t('cache_preference_updated'));
      } catch (error) {
        notify.error(this.$t('failed_update_cache_preferences'));
      } finally {
        this.loading_settings = false;
      }
    },
  },
});
</script>

