<template>
  <div class="grid-main">
    <div class="full-width">
      <q-markup-table
        flat
        class="dashboard-table-style dashboard-table-height back-white"
      >
        <thead>
          <tr class="table-header-text">
            <th>{{ $t('object') }}</th>
            <th>{{ $t('status') }}</th>
            <th style="width: 300px">{{ $t('ttl') }}</th>
          </tr>
        </thead>

        <tbody>
          <tr>
            <td>{{ $t('receive_delivery_cache') }}</td>
            <td>
              <f-toggle size="xs"
                :model-value="
                  cache_data[get_receive_delivery_cache]?.enabled || false
                "
                @update:model-value="updateEnable($event)"
              />
            </td>
            <td>
              <div style="width: 300px">
                <q-input
                  outlined
                  dense
                  tabindex="0"
                  debounce="500"
                  type="number"
                  :class="'full-width'"
                  :model-value="
                    cache_data[get_receive_delivery_cache]?.ttl || 0
                  "
                  @update:model-value="updateTtl(Number($event))"
                  hide-bottom-space
                  :bottom-slots="false"
                  style="padding: 5px 0px"
                >
                  <q-tooltip>
                    {{ $t('ttl_tooltip') }}
                  </q-tooltip>
                </q-input>
              </div>
            </td>
          </tr>
          <tr>
            <PurchaseOrderCach />
          </tr>
          <tr>
            <TaskAndNotificationCache />
          </tr>
        </tbody>
      </q-markup-table>
    </div>
  </div>
  <Loader />
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import { storeToRefs } from 'pinia';
import { useSettingStore } from 'src/store/main';
import { DeliveryCache } from 'src/constants';
import helperMixin from 'src/mixins/helperMixin';
import { ApiExceptions } from 'src/exceptions/index';
import Loader from 'components/Loader.vue';
import PurchaseOrderCach from 'src/pages/Settings/Components/CacheManagements/PurchaseOrderCach.vue';
import TaskAndNotificationCache from 'src/pages/Settings/Components/CacheManagements/TaskAndNotificationCache.vue';
import type { dynamicObj } from 'src/pages/assets';
export default defineComponent({
  components: { Loader, PurchaseOrderCach, TaskAndNotificationCache },
  el: '#app',
  mixins: [helperMixin],
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        if (newVal == true && oldVal == false) {
          return;
        }
      },
    },
    loading: {
      handler(newVal) {
        if (newVal == true) {
          this.showLoading();
        } else {
          this.hideLoading();
        }
      },
    },
  },
  data() {
    return {
      get_receive_delivery_cache: DeliveryCache.get_receive_delivery_cache,
      get_purchase_order_cache: DeliveryCache.get_purchase_order_cache,
      get_task_and_notification_cache:
        DeliveryCache.get_task_and_notification_cache,
    };
  },
  mounted() {
    this.init();
  },
  setup() {
    const settings_store = useSettingStore();
    const { user_settings, loading_settings, cache_data } =
      storeToRefs(settings_store);
    const { setCachePreferences, getCachePreferences, deleteCache } =
      settings_store;

    return {
      user_settings,
      cache_data,
      loading_settings,
      setCachePreferences,
      getCachePreferences,
      deleteCache,
      loading: ref(false),
    };
  },
  methods: {
    async init() {
      this.loading = true;
      try {
        await this.getCachePreferences(this.get_receive_delivery_cache);
        await this.getCachePreferences(this.get_purchase_order_cache);
        await this.getCachePreferences(this.get_task_and_notification_cache);
      } catch (e) {
        notify.error(this.$t('failed_to_get_cache_preferences'));
      } finally {
        this.loading = false;
      }
    },
    async updateEnable(value: boolean) {
      this.cache_data[this.get_receive_delivery_cache].enabled = value;
      await this.updateCache();
    },
    async updateTtl(value: number) {
      this.cache_data[this.get_receive_delivery_cache].ttl = value;
      await this.updateCache();
    },
    async updateCache() {
      const enabled = this.cache_data[this.get_receive_delivery_cache].enabled;
      const ttl = this.cache_data[this.get_receive_delivery_cache].ttl;
      await this.setCachePreferences(enabled, ttl)
        .then(() => {
          notify.success(this.$t('cache_preference_updated'));
        })
        .catch(() => {
          notify.error(this.$t('failed_update_cache_preferences'));
        })
        .finally(() => {
          this.loading = false;
        });
    },
  },
});
</script>

