<template>
  <div class="page-container page-height-limit">
    <div class="settings-page-content">
      <docbits-accordion-panel
        v-model="expandedSections.cache"
        icon="mdi:cached"
        :title="$t('cache_management')"
      >
        <template #header-actions>
          <f-btn
            :label="$t('clear_cache')"
            @click="clearCache"
            :loading="loading"
          />
        </template>
        <ReceivedCache />
      </docbits-accordion-panel>
    </div>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions';
import { useSettingStore } from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin';
import ReceivedCache from 'src/pages/Settings/Components/CacheManagements/ReceivedCache.vue';

export default defineComponent({
  el: '#app',
  components: {
    ReceivedCache,
  },
  mixins: [helperMixin],
  data() {
    return {
      loading: false,
      expandedSections: {
        cache: true,
      } as Record<string, boolean>,
    };
  },
  methods: {
    async clearCache() {
      this.loading = true;
      try {
        const response = await this.deleteCache();
        if (!response.success) {
          throw { message: response.message };
        }
        notify.success(this.$t('cache_cleared_successfully'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        console.error(err);
      } finally {
        this.loading = false;
      }
    },
  },
  setup() {
    const settings_store = useSettingStore();
    const { deleteCache } = settings_store;
    return {
      deleteCache,
    };
  },
});
</script>
<style scoped></style>
